package scan

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"

	"github.com/mellifera/mellifera/internal/access"
	"github.com/mellifera/mellifera/internal/naming"
	"github.com/mellifera/mellifera/internal/store"
)

// Identity adoption (tombstone-lifecycle D4, as amended 2026-11-09 — the
// post-red series bridge): when a rescan replaces a vanished file, the
// tombstoned predecessor's progress and ledger rows stay keyed to the dead
// id (retained by D5, join-dropped from served reads). AdoptStranded re-keys
// that stranded state onto the identity-matched live item. Episode pairs
// (legs on BOTH sides) match through the SERIES BRIDGE — equal, non-empty
// parser-composed series titles before the (season, episode) legs decide;
// the series path itself is never compared (renames change it). Film pairs
// match on equal AND non-empty item title floors (no identity facts, no
// adoption). No fuzzy matching: exact floors or a visible no-op (design
// R2). The hook fires from the enrich queue at a row's settle — the served
// identity facts exist only then, so this is what makes ONE rescan
// converge.
//
// adoptSweepPageSize is the candidate walk's page (store QueryItems
// LIMIT/OFFSET, id-ordered) — the item sweep's page width, for the same
// bounded-memory, stable-walk reason: adoption mutates ledger rows, never the
// items table's row set or order, so advancing OFFSET cannot skip candidates.
const adoptSweepPageSize = itemSweepPageSize

// AdoptStranded moves every tombstoned library sibling's stranded watch state
// onto the live item itemID when their served identities match. Candidates
// are EVERY status="deleted" row of the library — no carries-rows pre-filter
// (joined progress reads hide deleted rows and would see the candidates as
// empty; each MOVE's own returned count is the carry signal). Per candidate:
// MoveItemProgress + MoveItemWatched (the 2.1 transactions — idempotent); a
// (0, 0) return is a no-op skip. Every failure is log-and-skip — adoption
// NEVER fails its caller; the returned error is only the live-item read
// failing. A cancelled context stops the walk.
func AdoptStranded(ctx context.Context, st *store.Store, itemID string) error {
	// MUST-be-true read (access.System): the hook drives watch-state re-keying
	// — a scoped window could strand the live item's own identity unread.
	live, err := st.GetItem(ctx, itemID, access.System())
	if err != nil {
		return fmt.Errorf("scan: adoption: live item %s: %w", itemID, err)
	}
	liveDoc := naming.DocMap(live.Document)
	livePath, liveSeason, liveEpisode, liveHasLegs := naming.EpisodeFacts(liveDoc)
	liveIdent := adoptIdentity{
		title:      adoptTitleFloor(liveDoc),
		seriesPath: livePath,
		season:     liveSeason,
		episode:    liveEpisode,
		hasLegs:    liveHasLegs,
	}
	for offset := 0; ; offset += adoptSweepPageSize {
		// MUST-be-true read (access.System — scan is operator work): the
		// candidate walk must see every tombstoned row, and the exact
		// "deleted" status key (never a carries-rows pre-filter reader) is
		// what keeps the candidates visible at all (D4).
		cands, err := st.QueryItems(ctx, live.LibraryID, scanStatusDeleted, "", false, adoptSweepPageSize, offset, access.System())
		if err != nil {
			return fmt.Errorf("scan: adoption: candidates lib %d: %w", live.LibraryID, err)
		}
		for _, cand := range cands {
			if err := ctx.Err(); err != nil {
				return err
			}
			candDoc := naming.DocMap(cand.Document)
			if !adoptIdentityMatch(ctx, st, live.LibraryID, liveIdent, candDoc) {
				continue
			}
			movedProgress, err := st.MoveItemProgress(ctx, cand.ID, itemID)
			if err != nil {
				slog.Warn("scan: adoption: progress move failed — skipped", "from", cand.ID, "to", itemID, "error", err)
				continue
			}
			movedWatched, err := st.MoveItemWatched(ctx, cand.ID, itemID, livePath)
			if err != nil {
				slog.Warn("scan: adoption: watched move failed — skipped", "from", cand.ID, "to", itemID, "error", err)
				continue
			}
			if movedProgress == 0 && movedWatched == 0 {
				continue // carried nothing: the dead id held no stranded state — no-op skip
			}
			slog.Info("scan: adopted stranded watch state", "from", cand.ID, "to", itemID,
				"progress", movedProgress, "watched", movedWatched)
		}
		if len(cands) < adoptSweepPageSize {
			return nil
		}
	}
}

// adoptIdentity is one side's resolved identity facts — the live item's side
// is resolved once, before the candidate walk.
type adoptIdentity struct {
	title      string // the _view.title.value floor (the film shape's only title leg)
	seriesPath string // parsed.series_relative_path — the bridge's resolver key, never compared
	season     int64
	episode    int64
	hasLegs    bool
}

// adoptIdentityMatch reports whether candDoc's served identity equals the
// live item's under the amended D4 law (2026-11-09): episode pairs decide
// through the series bridge (equal non-empty parser-composed series titles,
// then the (season, episode) legs); film pairs on equal non-empty title
// floors. A one-legged pair never matches. No fuzzy matching (design R2).
func adoptIdentityMatch(ctx context.Context, st *store.Store, libraryID int64, live adoptIdentity, candDoc map[string]any) bool {
	candPath, candSeason, candEpisode, candHasLegs := naming.EpisodeFacts(candDoc)
	if candHasLegs != live.hasLegs {
		return false
	}
	if candHasLegs {
		liveSeries := adoptSeriesTitleFloor(ctx, st, libraryID, live.seriesPath)
		candSeries := adoptSeriesTitleFloor(ctx, st, libraryID, candPath)
		if liveSeries == "" || candSeries == "" || liveSeries != candSeries {
			return false
		}
		return candSeason == live.season && candEpisode == live.episode
	}
	// Films: the item title floor — the anti-degenerate law keeps an empty
	// floor on EITHER side from matching (D4's non-goal: no identity facts,
	// no adoption; "" == "" is legs-less identity, never a match).
	candTitle := adoptTitleFloor(candDoc)
	return live.title != "" && candTitle != "" && live.title == candTitle
}

// adoptSeriesTitleFloor resolves one side's bridge floor — the
// parser-composed series title: parsed.series_relative_path via
// GetSeriesByPath (status-unfiltered — the dead side's row is itself
// tombstoned and must still read), then the serial-parser title leg read
// inline (no namer dependency; tv-parser never writes series docs). Any miss
// floors to "": an empty floor is a no-match.
func adoptSeriesTitleFloor(ctx context.Context, st *store.Store, libraryID int64, seriesPath string) string {
	if seriesPath == "" {
		return ""
	}
	sr, err := st.GetSeriesByPath(ctx, libraryID, seriesPath, access.System())
	if err != nil {
		if !errors.Is(err, sql.ErrNoRows) {
			// adoption never fails its caller: an unexpected read error
			// floors "" — this candidate skips and the stranded state stays
			// keyed to the dead id (the honest no-op posture).
			slog.Warn("scan: adoption: series row read failed — bridge floor empty",
				"library", libraryID, "series_path", seriesPath, "error", err)
		}
		return ""
	}
	doc := naming.DocMap(sr.Document)
	sources, ok := doc["sources"].(map[string]any)
	if !ok {
		return ""
	}
	ns, ok := sources["serial-parser"].(map[string]any)
	if !ok {
		return ""
	}
	title, _ := ns["title"].(string)
	return title
}

// adoptTitleFloor is the _view.title.value floor inline read (the
// browse_wiring viewTitleFloor replication precedent — the naming original is
// unexported): a string passes verbatim, a json.Number renders losslessly
// (INV-no-rounding; naming.DocMap decodes with UseNumber), anything else floors
// to "".
func adoptTitleFloor(doc map[string]any) string {
	view, ok := doc["_view"].(map[string]any)
	if !ok {
		return ""
	}
	title, ok := view["title"].(map[string]any)
	if !ok {
		return ""
	}
	switch v := title["value"].(type) {
	case string:
		return v
	case json.Number:
		return v.String()
	default:
		return ""
	}
}
